import { onScopeDispose, ref, watch, type Ref } from 'vue';
import type { DraftRef, DraftSummary } from '../lib/ipc/client';

/** The longest preview kept in memory; the row clips it to one line with an ellipsis. */
const PREVIEW_LIMIT = 240;

/**
 * One line of plain literal text from a draft body: every run of whitespace and
 * control characters becomes one space, the ends are trimmed, and the length is
 * capped. The result is only ever rendered as a text node, never as HTML.
 */
export function previewText(body: string): string {
  return body.replace(/[\s\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, PREVIEW_LIMIT);
}

interface Entry { revision: number; text: string }

function previewKey(ref: DraftRef): string {
  return `${ref.accountId}:${ref.draftId}`;
}

/**
 * Body previews for the Drafts list. The draft summary has no body, so each
 * body is read once through `load` (an existing local read, `getDraft`) and kept
 * for its revision: a save that bumps the revision reads that draft again, an
 * unchanged draft is never read twice. A failed read shows nothing for that row
 * (no invented text) and is not repeated until the revision changes.
 */
export function useDraftPreviews(
  summaries: () => readonly DraftSummary[],
  load: (ref: DraftRef) => Promise<string>,
) {
  const entries: Ref<Record<string, Entry>> = ref({});
  const requested = new Map<string, number>();
  let disposed = false;

  async function read(summary: DraftSummary): Promise<void> {
    const key = previewKey(summary.ref);
    const revision = summary.revision;
    try {
      const body = await load(summary.ref);
      if (disposed) return;
      entries.value[key] = { revision, text: previewText(body) };
    } catch {
      // Nothing is shown for this row; the next revision tries again.
    }
  }

  watch(summaries, (list) => {
    const keys = new Set(list.map((summary) => previewKey(summary.ref)));
    for (const key of Object.keys(entries.value)) if (!keys.has(key)) delete entries.value[key];
    for (const key of [...requested.keys()]) if (!keys.has(key)) requested.delete(key);
    for (const summary of list) {
      const key = previewKey(summary.ref);
      if (requested.get(key) === summary.revision) continue;
      requested.set(key, summary.revision);
      void read(summary);
    }
  }, { immediate: true });

  onScopeDispose(() => { disposed = true; });

  /** The preview of this draft at its current revision: '' for an empty body, null while unknown. */
  function previewFor(summary: DraftSummary): string | null {
    const entry = entries.value[previewKey(summary.ref)];
    return entry && entry.revision === summary.revision ? entry.text : null;
  }

  return { previewFor };
}
<script setup lang="ts">
/**
 * The Reminders list context (fixture only): one Ash coverage line, in-flow
 * recovery lines, the in-flow picker (Remind me / Reschedule) and the rows of
 * the selected tab. The tabs themselves sit in the app header (the split-tab
 * slot) and read the same `model`. All request semantics live in
 * `useReminders`; this component only renders them.
 *
 * In Pending, rows that are not calmly waiting (failed, removing, returning,
 * cancelling) come first under one Ash caption, "Needs attention N"; the tab
 * count covers only phase `pending`. The data carries no failure cause, so the
 * failed note says what is known and no more, and Cancel is the only action:
 * no retry of a failed reminder exists.
 *
 * Esc inside the picker dismisses the picker alone; anywhere else Esc is the
 * app's Back. Row keys come from ContextRowList (J/K, arrows, Home, End).
 *
 * The app's key handler reaches the focused row through `rescheduleRow` (H)
 * and `cancelRow` (Shift+H): the same actions as the two row buttons, with the
 * same enabled rules, and a silent `false` for a row that does not offer the
 * action. Cancel keeps its immediate semantics. When a cancelled row leaves the
 * tab while focus is on <body>, focus moves to the next row (else the previous
 * one, else the pane). A polite status line names the tab after `[` / `]`.
 */
import { computed, nextTick, ref, watch } from 'vue';
import type { Reminder } from '../lib/ipc/client';
import { fullDateLabel } from '../lib/browsing-dates';
import { NEEDS_ATTENTION_LABEL, REMINDER_PHASES, REMINDERS_FIXTURE_DETAIL, REMINDERS_FIXTURE_LINE, type RemindersModel } from '../composables/useReminders';
import ContextRowList from './ContextRowList.vue';
import FullDate from './FullDate.vue';

const props = defineProps<{ model: RemindersModel }>();
const emit = defineEmits<{ open: [target: Reminder['conversation']] }>();
const {
  error, preparationError, preparationTarget, busy, loading, source, due, someday, condition, destination,
  displayed, attentionCount, activeRow, retrying, presetList, customForced, customShown, customOpen, tabAnnouncement,
} = props.model;

interface ReminderItem { key: string; reminder: Reminder }
const items = computed<ReminderItem[]>(() => displayed.value.map(reminder => ({ key: reminder.conversation.conversationId, reminder })));
const CANCELLABLE = ['removing', 'pending', 'returning', 'failed'];

const paneEl = ref<HTMLElement | null>(null);
const pickerEl = ref<HTMLElement | null>(null);
const list = ref<{ focusRow: (key: string | null, options?: { preventScroll?: boolean }) => Promise<void> } | null>(null);

/** Focus the current row, or the pane itself when the tab has no rows. */
async function focusRow(options: { preventScroll?: boolean } = {}): Promise<void> {
  await nextTick();
  if (list.value) await list.value.focusRow(activeRow.value, options);
  else paneEl.value?.focus(options);
}

function canReschedule(item: ReminderItem): boolean {
  return item.reminder.phase === 'pending' && !busy.value && !retrying.value;
}
function canCancel(item: ReminderItem): boolean {
  return CANCELLABLE.includes(item.reminder.phase) && !busy.value && !retrying.value;
}
function itemFor(key: string): ReminderItem | undefined {
  return items.value.find(item => item.key === key);
}
/** Open Reschedule for the row with this key, like its button. False when the row offers none. */
function rescheduleRow(key: string): boolean {
  const item = itemFor(key);
  if (!item || !canReschedule(item)) return false;
  props.model.reschedule(item.reminder);
  return true;
}
/** Cancel the row's reminder at once, like its button. False when the row offers none. */
function cancelRow(key: string): boolean {
  const item = itemFor(key);
  if (!item || !canCancel(item)) return false;
  const keys = items.value.map(candidate => candidate.key);
  const index = keys.indexOf(key);
  refocus = { key, neighbour: keys[index + 1] ?? keys[index - 1] ?? null };
  props.model.cancel(item.reminder);
  return true;
}
defineExpose({ focusRow, rescheduleRow, cancelRow, el: paneEl });

// A cancelled row leaves the tab a moment later. If it had keyboard focus, focus
// would fall to <body>, where the row keys no longer work.
let refocus: { key: string; neighbour: string | null } | null = null;
watch(() => items.value.map(item => item.key), async (keys) => {
  if (!refocus || keys.includes(refocus.key)) return;
  const { neighbour } = refocus;
  refocus = null;
  await nextTick();
  const active = document.activeElement;
  if (active && active !== document.body && active.isConnected) return;
  if (neighbour !== null && keys.includes(neighbour)) activeRow.value = neighbour;
  await focusRow();
});
/** Focus that moves to any other row ends the pending refocus. */
function onPaneFocusin(event: FocusEvent): void {
  const target = event.target;
  if (refocus && !(target instanceof HTMLElement && target.dataset.drawerRow === refocus.key)) refocus = null;
}

// The picker is an in-flow block: when it opens, focus moves to its first
// choice; when it closes while focus was inside it, focus returns to the rows.
watch(source, async (next, previous) => {
  await nextTick();
  if (next && !previous) pickerEl.value?.querySelector<HTMLElement>('button, input')?.focus();
  else if (!next && previous && (document.activeElement === document.body || document.activeElement === null)) await focusRow();
});

function dismiss() {
  props.model.dismissPicker();
  void focusRow();
}
function onPickerKeydown(event: KeyboardEvent) {
  if (event.key !== 'Escape' || event.isComposing || event.keyCode === 229 || event.ctrlKey || event.metaKey || event.altKey) return;
  // The picker owns this Escape: it must not also run the app's Back.
  event.stopPropagation(); event.preventDefault();
  if (busy.value || retrying.value) return;
  dismiss();
}
/** One quiet caption before the first row, only when rows need attention. */
function groupCaption(_item: ReminderItem, index: number): string | null {
  return index === 0 && attentionCount.value > 0 ? `${NEEDS_ATTENTION_LABEL} ${attentionCount.value}` : null;
}
function rowTitle(item: ReminderItem): string { return `Revision ${item.reminder.revision}`; }
</script>

<template>
  <div ref="paneEl" class="context-pane" data-test="reminders-panel" tabindex="-1" @focusin="onPaneFocusin">
    <!-- Honest state, once: the fixture disclosure is visible; the rest is its title and hidden text. -->
    <div class="context-coverage">
      <p class="cached-coverage" role="note" data-test="reminders-coverage" :title="REMINDERS_FIXTURE_DETAIL">{{ REMINDERS_FIXTURE_LINE }}<span class="visually-hidden"> · {{ REMINDERS_FIXTURE_DETAIL }}</span></p>
      <button type="button" class="drawer-quiet" data-test="reminders-refresh" :disabled="busy" @click="model.retryOrRefresh()">{{ retrying ? 'Retry exact request' : 'Refresh reminders' }}</button>
    </div>
    <div v-if="error" class="recovery-banner" data-test="reminders-error">
      <p role="alert">{{ error }}</p>
      <button v-if="retrying" type="button" :disabled="busy" @click="model.inspectDurableState()">Inspect durable state</button>
    </div>
    <div v-if="preparationError" class="recovery-banner" data-test="reminders-preparation-error">
      <p role="alert">{{ preparationError }}</p>
      <button v-if="preparationTarget" type="button" :disabled="busy || retrying" @click="model.prepare(preparationTarget)">{{ busy ? 'Preparing current source…' : 'Retry preparation / refresh source' }}</button>
    </div>
    <form
      v-if="source"
      ref="pickerEl"
      class="reminder-form"
      data-test="reminder-form"
      :data-source-conversation="source.conversation.conversationId"
      :data-source-message="source.sourceMessageId"
      @submit.prevent="model.submit()"
      @keydown="onPickerKeydown"
    >
      <h2 class="drawer-section-title">{{ source.revision === null ? 'Remind me' : 'Reschedule' }}</h2>
      <!-- The subject names the mail; the opaque ids stay in the title and data attributes. -->
      <p class="reminder-subject" :title="`Conversation ${source.conversation.conversationId} · source ${source.sourceMessageId}`">{{ source.subject || '(No subject)' }}</p>
      <fieldset class="reminder-fields" :disabled="busy || retrying">
        <div class="reminder-presets" role="group" aria-label="Return time">
          <button
            v-for="preset in presetList"
            :key="preset.id"
            type="button"
            class="drawer-chip"
            :data-test="`reminder-preset-${preset.id}`"
            :aria-pressed="!someday && due === preset.at"
            :title="fullDateLabel(preset.at)"
            @click="model.choosePreset(preset.at)"
          >{{ preset.label }}</button>
          <label class="reminder-someday" title="Someday — no automatic return"><input v-model="someday" type="checkbox"> Someday</label>
          <button
            v-if="!someday"
            type="button"
            class="drawer-chip"
            data-test="reminder-custom"
            :aria-expanded="customShown"
            aria-controls="reminder-custom-field"
            :disabled="customForced"
            @click="customOpen = !customOpen"
          >Custom</button>
        </div>
        <div v-if="!someday && customShown" id="reminder-custom-field" class="reminder-custom">
          <label class="field-row"><span class="field-label reminder-label">Time with timezone offset</span>
            <input v-model="due" class="field-input" required type="text" placeholder="2030-11-03T09:00:00-05:00" aria-describedby="reminder-time-help">
          </label>
          <p id="reminder-time-help" class="drawer-note">Use RFC3339 with Z or a numeric offset. No ambiguous local times or automatic DST adjustment.</p>
        </div>
        <label class="field-row"><span class="field-label reminder-label">Return condition</span>
          <select v-model="condition" class="field-input"><option value="if_no_reply">If no reply (default)</option><option value="regardless">Regardless of reply</option></select>
        </label>
        <div class="reminder-actions">
          <button type="submit" class="drawer-primary" :disabled="!someday && due.trim() === ''">{{ source.revision === null ? 'Schedule and remove from Inbox' : 'Save new time' }}</button>
          <button type="button" class="drawer-quiet" @click="dismiss()">Dismiss picker</button>
        </div>
      </fieldset>
    </form>
    <!-- Names the tab after `[` / `]`; mounted all the time so each change is announced. -->
    <p class="visually-hidden" role="status" aria-live="polite" data-test="reminders-tab-status">{{ tabAnnouncement }}</p>
    <div id="reminder-tabpanel" role="tabpanel" :aria-labelledby="`reminder-tab-${destination}`">
      <p v-if="loading" class="list-state" role="status">Loading local reminders…</p>
      <p v-else-if="!displayed.length" class="list-state" data-test="reminders-empty">No {{ destination }} reminders.</p>
      <ContextRowList
        v-if="items.length"
        ref="list"
        :items="items"
        :label="`${destination[0]!.toUpperCase()}${destination.slice(1)} reminders`"
        :active-key="activeRow"
        :row-title="rowTitle"
        :group-caption="groupCaption"
        :row-test-id="(item: ReminderItem) => `reminder-row-${item.reminder.phase}`"
        @update:active-key="activeRow = $event"
        @open="emit('open', $event.reminder.conversation)"
      >
        <template #primary="{ item }"><span class="context-subject">{{ item.reminder.subject || '(No subject)' }}</span></template>
        <template #secondary="{ item }"><span v-if="item.reminder.condition === 'regardless'" data-test="reminder-condition">Returns regardless of reply</span></template>
        <template #actions="{ item }">
          <button v-if="item.reminder.phase === 'pending'" type="button" class="drawer-quiet" title="Reschedule — H" aria-keyshortcuts="H" :disabled="busy || retrying" @click="model.reschedule(item.reminder)">Reschedule</button>
          <button
            v-if="CANCELLABLE.includes(item.reminder.phase)"
            type="button"
            class="drawer-quiet"
            :aria-label="item.reminder.phase === 'failed' ? 'Cancel reminder and recover original inbox messages' : 'Cancel reminder and restore original inbox messages'"
            :title="`${item.reminder.phase === 'failed' ? 'Cancel / recover original inbox messages' : 'Cancel and restore original inbox messages'} — Shift+H`"
            aria-keyshortcuts="Shift+H"
            :disabled="busy || retrying"
            @click="model.cancel(item.reminder)"
          >Cancel reminder</button>
        </template>
        <template #trailing="{ item }">
          <span class="context-date"><FullDate v-if="item.reminder.dueAt" :at="item.reminder.dueAt" /><template v-else>Someday</template></span>
          <span class="activity-status context-phase" :class="`tone-${REMINDER_PHASES[item.reminder.phase].tone}`" :data-test="`reminder-phase-${item.reminder.phase}`">{{ REMINDER_PHASES[item.reminder.phase].word }}</span>
        </template>
        <template #note="{ item }">
          <p v-if="item.reminder.phase === 'failed'" class="context-row-note tone-fault">A mailbox change failed or newer triage superseded it; which one is not recorded. Cancel does not override newer triage.</p>
        </template>
      </ContextRowList>
    </div>
  </div>
</template>

<style scoped>
.reminder-form, .reminder-fields { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.reminder-form { padding: 6px 24px 12px 50px; overflow-wrap: anywhere; }
.reminder-fields { border: 0; margin: 0; padding: 0; }
.reminder-form .drawer-section-title { margin: 0; }
.reminder-subject { margin: 0; color: var(--text-primary); font-weight: var(--weight-strong); }
.reminder-presets { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-left: -8px; }
.reminder-someday { display: inline-flex; align-items: center; gap: 6px; padding: 4px 8px; }
.reminder-custom { display: flex; flex-direction: column; gap: 4px; }
.reminder-label { flex: 0 0 9rem; }
.reminder-actions { display: flex; align-items: center; gap: 6px; margin: 6px 0 0 -8px; }
</style>
<script setup lang="ts" generic="T extends { key: string }">
/**
 * Rows of a list context whose rows are not threads (Reminders, Drafts):
 * the Conversation Row geometry of DESIGN.md with slots instead of sender,
 * subject and snippet.
 *
 * - 36px rows on 12px type, inset 6px from both pane edges, a 44px gutter
 *   (`lead`), the text on the 50px content inset, the trailing slot about 25px
 *   from the pane edge. No row borders: rows are separated by rhythm alone.
 * - The current row is the one signal: Focus Stone fill plus the 4px Dusk
 *   Lavender bar, and `aria-current` on its item, like InboxList.
 * - One real button per row (`primary`) is the row's action and its keyboard
 *   marker. `secondary` is a quiet Ash line beside it, outside the button's
 *   name. ArrowUp/ArrowDown or J/K, Home and End move between rows through
 *   `useDrawerRows` (roving tabindex, no wrap; editable targets, IME and
 *   modified keys are ignored). Enter and Space stay native. The trailing slot
 *   and the row `actions` are not rows: they keep native Tab and Enter and
 *   stay Tab-reachable. Escape is the app's.
 * - Clicking the row outside any control opens it, like an Inbox row.
 * - `groupCaption` may name a quiet Ash caption that precedes an item (a
 *   non-actionable `presentation` line, as in the Inbox's date captions). It
 *   sits in the same list, so row keys keep moving across it.
 * - `note` is an exception line under its row (Coral or Amber), only where one
 *   applies.
 */
import { computed, nextTick, ref } from 'vue';
import { useDrawerRows } from '../composables/useDrawerRows';

const props = defineProps<{
  items: readonly T[];
  /** The list's accessible name. */
  label: string;
  /** The remembered current row key (restored after a reader round trip). */
  activeKey?: string | null;
  /** Visually hidden verb that starts the open button's accessible name. */
  openVerb?: string;
  /** Hover title of the open button (for example a revision). */
  rowTitle?: (item: T) => string | undefined;
  rowTestId?: (item: T) => string | undefined;
  /** A caption shown before this item, or null/undefined for none. */
  groupCaption?: (item: T, index: number) => string | null | undefined;
  /** Test hook of the open button (the row's marker element). */
  openTestId?: (item: T) => string | undefined;
  /** Rows cannot be opened while true (an editor transition is running). */
  disabled?: boolean;
}>();
const emit = defineEmits<{ open: [item: T]; 'update:activeKey': [key: string] }>();

const listEl = ref<HTMLElement | null>(null);
const rows = useDrawerRows({ keys: () => props.items.map(item => item.key), initial: () => props.activeKey ?? null });
/** The current row: the remembered one, else the first (the Tab stop). */
const currentKey = computed(() => {
  const keys = props.items.map(item => item.key);
  return rows.active.value !== null && keys.includes(rows.active.value) ? rows.active.value : keys[0] ?? null;
});

/** Opening a row also makes it the remembered current row, so Back lands on it. */
function open(item: T): void {
  if (props.disabled) return;
  emit('update:activeKey', item.key);
  emit('open', item);
}

function onRowClick(event: MouseEvent, item: T): void {
  const target = event.target;
  if (target instanceof Element && target.closest('button, a, input, select, textarea, label')) return;
  open(item);
}

/** Focus one row's button (or the list itself when there is no row to take it). */
async function focusRow(key: string | null, options: { preventScroll?: boolean } = {}): Promise<void> {
  await nextTick();
  const button = key === null ? null : [...(listEl.value?.querySelectorAll<HTMLElement>('[data-drawer-row]') ?? [])]
    .find(el => el.dataset.drawerRow === key) ?? null;
  const first = listEl.value?.querySelector<HTMLElement>('[data-drawer-row]') ?? null;
  (button ?? first ?? listEl.value)?.focus({ preventScroll: options.preventScroll ?? false });
}

defineExpose({ focusRow, el: listEl });
</script>

<template>
  <ul ref="listEl" class="context-list" role="list" :aria-label="label" tabindex="-1" @keydown="rows.onKeydown">
    <template v-for="(item, index) in items" :key="item.key">
      <li v-if="groupCaption?.(item, index)" class="context-group" role="presentation" data-test="context-group">{{ groupCaption(item, index) }}</li>
      <li
        class="context-item"
        role="listitem"
        :aria-current="currentKey === item.key ? 'true' : undefined"
        :data-test="rowTestId?.(item)"
      >
        <div class="context-row" :class="{ focused: currentKey === item.key }" @click="onRowClick($event, item)">
          <span class="context-row-lead"><slot name="lead" :item="item" /></span>
          <button
            type="button"
            class="context-row-main"
            v-bind="rows.rowAttrs(item.key)"
            :title="rowTitle?.(item)"
            :data-test="openTestId?.(item)"
            :disabled="disabled || undefined"
            @focus="emit('update:activeKey', item.key)"
            @click="open(item)"
          >
            <span class="visually-hidden">{{ `${openVerb ?? 'Open'} ` }}</span>
            <span class="context-row-primary"><slot name="primary" :item="item" /></span>
          </button>
          <span class="context-row-secondary"><slot name="secondary" :item="item" /></span>
          <span class="context-row-actions"><slot name="actions" :item="item" /></span>
          <span class="context-row-trailing"><slot name="trailing" :item="item" /></span>
        </div>
        <slot name="note" :item="item" />
      </li>
    </template>
  </ul>
</template>
